<template>
  <div class="agent-run-card" :class="'agent-run-card--' + run.status">
    <!-- Header -->
    <div class="run-header">
      <q-avatar size="28px" icon="smart_toy" class="run-avatar" />
      <div class="run-header__info">
        <strong>{{ run.agent_name }}</strong>
        <q-badge color="dark" :label="'Run ' + shortId" class="run-badge" />
        <q-badge :color="statusBadgeColor" :label="run.status" outline class="status-badge" />
      </div>
      <q-space />
      <span class="text-caption text-grey-6">{{ formatDate(run.started_at || run.created_on) }}</span>
      <template v-if="run.status === 'running'">
        <q-btn flat dense size="sm" color="negative" :label="$t('stop')" icon="stop" data-testid="stop-btn" @click="$emit('stop', run.id)" />
      </template>
    </div>

    <!-- Live event stream (when running) -->
    <div v-if="run.status === 'running' && run.events.length > 0" class="run-events" ref="eventsContainer">
      <div v-for="(evt, i) in run.events" :key="i" class="run-event">
        <span class="run-event__type">{{ evt.type }}</span>
        <span class="run-event__tool" v-if="evt.data?.tool_name">{{ evt.data.tool_name }}</span>
        <span class="run-event__time text-grey-7">{{ formatTime(evt.timestamp) }}</span>
      </div>
    </div>

    <!-- Result (when completed) -->
    <div v-if="run.status !== 'running' && run.result_text" class="run-result">
      <div class="run-result__text markdown-body" v-html="renderedResult" />
    </div>

    <!-- Footer -->
    <div v-if="run.status !== 'running' && run.error" class="run-footer">
      <span class="text-caption text-negative">{{ run.error }}</span>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetAgentRun } from 'src/@types/docnet';
import { renderMarkdown } from 'src/utils/markdown';

export default defineComponent({
  name: 'AgentRunCard',
  props: {
    run: { type: Object as PropType<DocNetAgentRun>, required: true },
  },
  emits: ['stop'],
  computed: {
    shortId(): string {
      return this.run.id.slice(0, 8);
    },
    statusBadgeColor(): string {
      const map: Record<string, string> = {
        running: 'warning',
        succeeded: 'positive',
        failed: 'negative',
        stopped: 'grey',
      };
      return map[this.run.status] || 'grey';
    },
    tokenCount(): number {
      const u = this.run.token_usage;
      if (!u) return 0;
      // Support both backend formats: {total, prompt, completion} and {total, input, output}
      return (u as any).total || ((u as any).prompt || 0) + ((u as any).completion || 0) || (u.input || 0) + (u.output || 0);
    },
    renderedResult(): string {
      return renderMarkdown(this.run.result_text || '');
    },
  },
  watch: {
    'run.events.length'() {
      this.$nextTick(() => {
        const el = this.$refs.eventsContainer as HTMLElement;
        if (el) el.scrollTop = el.scrollHeight;
      });
    },
  },
  methods: {
    formatDate(isoString?: string): string {
      if (!isoString) return '';
      const date = new Date(isoString);
      const now = new Date();
      const diffMin = Math.floor((now.getTime() - date.getTime()) / 60000);
      if (diffMin < 1) return 'just now';
      if (diffMin < 60) return `${diffMin}m ago`;
      return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
    },
    formatTime(isoString: string): string {
      return new Date(isoString).toLocaleTimeString(undefined, {
        hour: '2-digit', minute: '2-digit', second: '2-digit',
      });
    },
  },
});
</script>

